<?php /* My Pay tabs: payslips, own claims and (approvers) the claim queue. $active: payslips|mine|queue, optional $queueCount */
$t = array_filter(['payslips' => can('payroll.view_own') ? ['Payslips', '/payslips', 'file-text'] : null, 'mine' => can('payroll.reimbursements.request') && feature_on('reimbursements') ? ['My claims', '/reimbursements?tab=mine', 'receipt'] : null,
  'queue' => can('payroll.reimbursements.approve') && feature_on('reimbursements') ? ['Claim approvals', '/reimbursements?tab=queue', 'check-square'] : null]);
if (count($t) > 1): ?><nav class="tabs mb" aria-label="Pay sections"><?php foreach ($t as $k => [$l, $u, $ic]): ?><a href="<?= e(url($u)) ?>" class="<?= $k === $active ? 'active' : '' ?>"<?= $k === $active ? ' aria-current="page"' : '' ?>><?= icon($ic, 'sm') ?> <?= e($l) ?><?php if ($k === 'queue' && !empty($queueCount)): ?> <span class="pill pill-lemon"><?= (int) $queueCount ?></span><?php endif ?></a><?php endforeach ?></nav><?php endif ?>
